import React, { useEffect, useState } from 'react';
import panda1 from './panda.png';
import panda2 from './pandaa.png';
import './App.css';

function FloatingPandas() {
  // Create 10 pandas: 5 of each image
  const initialPandas = [];
  for (let i = 0; i < 5; i++)
    initialPandas.push({
      src: panda1,
      x: 50 + Math.random() * 500,
      y: 50 + Math.random() * 300,
      dx: 1 + Math.random() * 2,
      dy: 1 + Math.random() * 2,
    });
  for (let i = 0; i < 5; i++)
    initialPandas.push({
      src: panda2,
      x: 100 + Math.random() * 500,
      y: 200 + Math.random() * 300,
      dx: 1 + Math.random() * 2,
      dy: 1 + Math.random() * 2,
    });

  const [pandas, setPandas] = useState(initialPandas);
  const [chartBounds, setChartBounds] = useState([]);

  // Get chart container positions dynamically
  useEffect(() => {
    const updateBounds = () => {
      const containers = document.querySelectorAll('.chart-container');
      const bounds = Array.from(containers).map(c => c.getBoundingClientRect());
      setChartBounds(bounds);
    };

    updateBounds(); // initial bounds
    window.addEventListener('resize', updateBounds); // recalc on resize

    return () => window.removeEventListener('resize', updateBounds);
  }, []);

  // Move pandas and bounce off chart containers
  useEffect(() => {
    const interval = setInterval(() => {
      setPandas(prev =>
        prev.map(p => {
          let newX = p.x + p.dx;
          let newY = p.y + p.dy;

          chartBounds.forEach(bound => {
            const pandaRight = newX + 80;
            const pandaBottom = newY + 80;

            const overlapX = pandaRight > bound.left && newX < bound.right;
            const overlapY = pandaBottom > bound.top && newY < bound.bottom;

            if (overlapX && overlapY) {
              // Bounce horizontally or vertically
              if (overlapX) p.dx = -p.dx;
              if (overlapY) p.dy = -p.dy;
              newX = p.x + p.dx;
              newY = p.y + p.dy;
            }
          });

          // Bounce off window edges
          if (newX <= 0 || newX + 80 >= window.innerWidth) p.dx = -p.dx;
          if (newY <= 0 || newY + 80 >= window.innerHeight) p.dy = -p.dy;

          return { ...p, x: newX, y: newY };
        })
      );
    }, 30);

    return () => clearInterval(interval);
  }, [chartBounds]);

  return (
    <>
      {pandas.map((p, i) => (
        <img
          key={i}
          src={p.src}
          alt={`panda${i}`}
          className="panda"
          style={{
            left: p.x,
            top: p.y,
            position: 'fixed',
            width: 80,
            height: 80,
            pointerEvents: 'none',
            zIndex: 10,
          }}
        />
      ))}
    </>
  );
}

export default FloatingPandas;
